SELECT CONCAT('frozen_', pp.id) AS row_label, s.atr_percent, s.atr_at_signal, pp.entry_price, s.atr_at_signal / NULLIF(pp.entry_price, 0) * 100 AS atr_pct_recomputed, (pp.entry_price - pp.stop_loss) / NULLIF(pp.entry_price, 0) * 100 AS stop_pct, pp.entry_price * pp.quantity AS notional FROM crypto_ai.paper_position pp JOIN crypto_ai.trade_signal s ON s.id = pp.signal_id WHERE pp.id IN (137,143,158,162,172,182) UNION ALL SELECT 'population_total', NULL, NULL, NULL, NULL, COUNT(*), SUM(pp.entry_price * pp.quantity) FROM crypto_ai.paper_position pp WHERE pp.status IN ('CLOSED','STOPPED') LIMIT 10